import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-26","description":"","frontmatter":{"title":"AI 动态 · 2026-11-26","date":"2026-11-26T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-26.md","filePath":"news/2026-11/ai-news-2026-11-26.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-26.md"};function i(o,e,c,l,p,d){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-26" tabindex="-1">AI 动态 · 2026-11-26 <a class="header-anchor" href="#ai-动态-·-2026-11-26" aria-label="Permalink to &quot;AI 动态 · 2026-11-26&quot;">​</a></h1><blockquote><p>截至 2026-11-26。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>今日最大看点是 Anthropic 上市后股价数日内暴跌 31% 跌破发行价，同时 Claude Code 核心开发者接连被 OpenAI 挖走，编程王座之争骤然升温。</li><li>监管与治理压力同步加码：标普考虑因治理与关键人风险下调英伟达信用评级，纽约州禁售 AI 聊天玩具五年，42 州总检察长联手阻止 Character.AI 出售用户聊天数据。</li><li>产品与基础设施侧，OpenAI 合并 Chat 与 Work 并统一用量计量，FCC 批准 SpaceX 最多 100 万颗 AI 数据中心卫星，MCP 服务器开始能下发 Agent 技能。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-anthropic-上市即破发-claude-code-核心班底被-openai-收割" tabindex="-1">头条 · Anthropic 上市即破发，Claude Code 核心班底被 OpenAI 收割 <a class="header-anchor" href="#头条-·-anthropic-上市即破发-claude-code-核心班底被-openai-收割" aria-label="Permalink to &quot;头条 · Anthropic 上市即破发，Claude Code 核心班底被 OpenAI 收割&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/0d9c61147d78.webp" alt="配图"></p><p>Anthropic 上市后股价数日内暴跌 31%，跌破发行价；更棘手的是多名 Claude Code 核心开发者相继离职并加入 OpenAI，Cat Wu、Thariq Shihipar、Anthony Morris 三人构成关键人才迁移链。对读者：评估编码 Agent 供应商时，除模型能力外应把团队稳定性与路线连续性纳入风险清单，避免把关键工作流押在动荡期产品上。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/z9IwzAY8hP15oDa2VKi6?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-ceo-dario-amodei-称「向-ai-交出人类控制权」的指控荒谬" tabindex="-1">Anthropic CEO Dario Amodei 称「向 AI 交出人类控制权」的指控荒谬 <a class="header-anchor" href="#anthropic-ceo-dario-amodei-称「向-ai-交出人类控制权」的指控荒谬" aria-label="Permalink to &quot;Anthropic CEO Dario Amodei 称「向 AI 交出人类控制权」的指控荒谬&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/0840fabce6ba.jpg" alt="配图"></p><p>Anthropic CEO Dario Amodei 回击竞争对手的指控，否认自己主张把人类能动性交给 AI，尽管领先 AI 公司正越来越多地自动化自身研究与模型开发。对读者：安全叙事正成为模型厂商的竞争话术，选型时可要求供应商给出可验证的人工介入与审计机制，而非只听立场表态。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/25/anthropics-dario-amodei-calls-accusations-of-surrendering-human-control-to-ai-absurd/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="英国-fca-抱怨-meta-拒绝共享-muse-供测试" tabindex="-1">英国 FCA 抱怨 Meta 拒绝共享 Muse 供测试 <a class="header-anchor" href="#英国-fca-抱怨-meta-拒绝共享-muse-供测试" aria-label="Permalink to &quot;英国 FCA 抱怨 Meta 拒绝共享 Muse 供测试&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/80feb76c248b.jpg" alt="配图"></p><p>英国金融行为监管局（FCA）警告 AI 智能体可能带来「另一股攻击力量」，此前 Meta 拒绝在周二于英国推出个人智能体前进行联合测试的请求。对读者：面向金融场景的 Agent 上线前，主动与监管沟通测试安排比事后解释更省成本，尤其是涉及账户与支付动作的产品。</p><p class="news-entry-source"><a href="https://www.wired.com/story/meta-refused-to-share-muse-for-testing-uk-financial-watchdog-complains/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="_42-州总检察长联手阻止-character-ai-出售用户聊天记录" tabindex="-1">42 州总检察长联手阻止 Character.AI 出售用户聊天记录 <a class="header-anchor" href="#_42-州总检察长联手阻止-character-ai-出售用户聊天记录" aria-label="Permalink to &quot;42 州总检察长联手阻止 Character.AI 出售用户聊天记录&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/457a2017e30a.jpg" alt="配图"></p><p>42 位州总检察长组成联盟，试图阻止 Character.AI 在破产程序中出售用户数据，称其计划拍卖超过 2100 万个美国账户的私密聊天历史，其中逾 210 万个注册为未成年人，且缺乏保障措施。对读者：涉及用户对话数据的产品应尽早明确数据资产边界与破产场景下的处置条款，隐私政策里写不清的部分，监管会替你写。</p><p class="news-entry-source"><a href="https://www.theverge.com/policy/1042620/character-ai-sale-state-ags-block-selling-users-chats" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-合并-chat-与-work-重度用户可能更早触达用量上限" tabindex="-1">OpenAI 合并 Chat 与 Work，重度用户可能更早触达用量上限 <a class="header-anchor" href="#openai-合并-chat-与-work-重度用户可能更早触达用量上限" aria-label="Permalink to &quot;OpenAI 合并 Chat 与 Work，重度用户可能更早触达用量上限&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/cba6b7779fc2.jpg" alt="配图"></p><p>OpenAI 将把 ChatGPT 的 Chat 与 Work 体验合并，并引入统一的用量计量表，这意味着重度用户可能比过去更早触及限额。对读者：把 ChatGPT 深度嵌入日常流程的团队应重新核算额度消耗，提前准备降级模型或备用通道，避免统一计量后成本与中断风险同时上升。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/25/openai-says-heavy-chatgpt-users-may-hit-limits-sooner-as-it-merges-chat-and-work/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="fcc-批准-spacex-最多部署-100-万颗数据中心卫星" tabindex="-1">FCC 批准 SpaceX 最多部署 100 万颗数据中心卫星 <a class="header-anchor" href="#fcc-批准-spacex-最多部署-100-万颗数据中心卫星" aria-label="Permalink to &quot;FCC 批准 SpaceX 最多部署 100 万颗数据中心卫星&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/f558249e4c09.jpg" alt="配图"></p><p>FCC 批准 SpaceX 的「Starmind」计划，允许其部署最多 100 万颗搭载 AI 芯片的卫星，这是该机构首次批准完整的 AI 卫星星座；要求 2033 年前至少部署一颗，2040 年达到 100 万颗里程碑。对读者：太空算力从概念进入许可阶段，长期看将改变推理基础设施的地理分布，值得关注其对延迟敏感型应用与能源约束的潜在影响。</p><p class="news-entry-source"><a href="https://www.theverge.com/science/1042278/spacex-fcc-starmind-ai-space-data-centers" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nothing-公布-ai-耳机-ear-note-与可录音充电盒" tabindex="-1">Nothing 公布 AI 耳机 Ear Note 与可录音充电盒 <a class="header-anchor" href="#nothing-公布-ai-耳机-ear-note-与可录音充电盒" aria-label="Permalink to &quot;Nothing 公布 AI 耳机 Ear Note 与可录音充电盒&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/a3a7c6eb3aa0.jpg" alt="配图"></p><p>Nothing 在 12 月 8 日发布前展示 Ear Note 耳机细节：耳机可录制通话，充电盒可录制、转写并总结对话，盒上新增「Record」按钮，另有「Talk」按钮录制本人语音。对读者：会议记录类硬件正把转写与摘要下沉到配件层，评估此类产品时应重点确认录音合规提示与数据存储位置。</p><p class="news-entry-source"><a href="https://www.theverge.com/gadgets/1042162/nothing-ear-note-ai-earbuds-reveal" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="mcp-服务器现在可下发-agent-技能-企业审批范围随之改变" tabindex="-1">MCP 服务器现在可下发 Agent 技能，企业审批范围随之改变 <a class="header-anchor" href="#mcp-服务器现在可下发-agent-技能-企业审批范围随之改变" aria-label="Permalink to &quot;MCP 服务器现在可下发 Agent 技能，企业审批范围随之改变&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-11-26">2026-11-26</time></p><p>MCP 服务器如今能够直接交付 AI Agent 技能，这改变了企业在连接一个 MCP 服务器时实际批准的内容边界——不再只是数据访问，还包括可执行能力。对读者：接入第三方 MCP 服务器前应把「技能清单」纳入安全评审，明确可调用工具与权限范围，避免一次连接引入未审计的自动化能力。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMizAFBVV95cUxNS0VjTnRXOWNYWjBfbXlPSnZfV1pBX1RIZnRxcU9la0I2NU1QVzdhZ0lMRExmQUlpNUgwQktub0ZYSG15czE5bzBTaVNBXy1sRGVyQnRHcVdnTXl3aW96S0NScEczQ3pFODZiV1czdm5HdExPbDhTLTlNYVpScFRyMzgzTkNhbE84blNkZTZ1Q3F6dUtMZjVnbGRGZnI5Z2ZWTHh6RWdGRy1NNG43UXN1ZlY0OEVNLTh1NTEzZUhBMXEzZnZOeUpsY2FzTkY?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="llama-cpp-推出-amd-ryzen-与-radeon-基准测试面板" tabindex="-1">llama.cpp 推出 AMD Ryzen 与 Radeon 基准测试面板 <a class="header-anchor" href="#llama-cpp-推出-amd-ryzen-与-radeon-基准测试面板" aria-label="Permalink to &quot;llama.cpp 推出 AMD Ryzen 与 Radeon 基准测试面板&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c5de500cb142.webp" alt="配图"></p><p>ggml-org 在 Hugging Face 发布 llama.cpp 面向 AMD Ryzen 与 Radeon 的基准测试面板，为本地推理在 AMD 平台上的性能对比提供统一参考。对读者：计划用 AMD 硬件跑本地模型的团队可先用该面板核对吞吐与延迟数据，再决定采购与量化配置，减少试错成本。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/ggml-org/llamacpp-amd-bench" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nvidia-发布-nemotron-3-5-parse-的开放数据、微调与加速推理实践" tabindex="-1">NVIDIA 发布 Nemotron 3.5 Parse 的开放数据、微调与加速推理实践 <a class="header-anchor" href="#nvidia-发布-nemotron-3-5-parse-的开放数据、微调与加速推理实践" aria-label="Permalink to &quot;NVIDIA 发布 Nemotron 3.5 Parse 的开放数据、微调与加速推理实践&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/46f3fbb78073.webp" alt="配图"></p><p>NVIDIA 在 Hugging Face 撰文介绍如何基于 Nemotron 3.5 Parse 使用开放数据进行微调并实现更快推理，覆盖数据、训练与部署链路。对读者：需要文档解析类能力的团队可据此评估自托管方案，重点比对微调后的领域精度与推理成本是否优于直接调用闭源 API。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/nvidia/building-on-nemotron-35-parse-open-data-fine-tunin" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="多智能体系统如何构建、训练与评估" tabindex="-1">多智能体系统如何构建、训练与评估 <a class="header-anchor" href="#多智能体系统如何构建、训练与评估" aria-label="Permalink to &quot;多智能体系统如何构建、训练与评估&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/cc1bd266407a.png" alt="配图"></p><p>Hugging Face 博客以「Swarms、Flocks、Gangs」为题，系统梳理多智能体系统的构建、训练与评估方法，覆盖协作拓扑与评测口径。对读者：正在把单 Agent 拆成多 Agent 的团队可借此建立评估基线，避免只凭演示效果判断系统可靠性。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/training-swarms" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="uber-开源思路-对-ai-智能体做全生命周期行为治理" tabindex="-1">Uber 开源思路：对 AI 智能体做全生命周期行为治理 <a class="header-anchor" href="#uber-开源思路-对-ai-智能体做全生命周期行为治理" aria-label="Permalink to &quot;Uber 开源思路：对 AI 智能体做全生命周期行为治理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b95b6099af59.jpg" alt="配图"></p><p>Uber 工程团队指出传统身份与 API 管控难以防护会动态解析外部内容、执行真实操作的 AI 智能体，为此自研框架，结合用户请求、智能体目标、权限与交互上下文校验行为合规，覆盖注册准入、运行时评估与持续保障。对读者：构建可执行操作的 Agent 平台时，可参考其分层鉴权思路，把提示注入与目标劫持纳入运行时防护而非仅靠提示词约束。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/xA3g2i0VtTZIOVePMedY?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="snowflake-coco-进化-数据开发进入-agent-自主执行" tabindex="-1">Snowflake CoCo 进化：数据开发进入 Agent 自主执行 <a class="header-anchor" href="#snowflake-coco-进化-数据开发进入-agent-自主执行" aria-label="Permalink to &quot;Snowflake CoCo 进化：数据开发进入 Agent 自主执行&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/31f8c6474927.jpg" alt="配图"></p><p>Snowflake CoCo 最新更新允许团队把复杂任务交给自主运行的云端智能体，即使用户离开，智能体也能在安全沙箱与企业治理框架下持续工作，并集成子智能体、实时预览与原生 Git 操作。对读者：数据平台选型时可把「无人值守任务」的治理与审计能力作为硬指标，而非只看 Agent 能否跑通演示。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/vfmBDlfQRRfHq4Jyi5b6?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="pages-data-sdk-上线-前端页面不建后端也能读写云端数据" tabindex="-1">Pages Data SDK 上线：前端页面不建后端也能读写云端数据 <a class="header-anchor" href="#pages-data-sdk-上线-前端页面不建后端也能读写云端数据" aria-label="Permalink to &quot;Pages Data SDK 上线：前端页面不建后端也能读写云端数据&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-26">2026-11-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/5ee0875f1dc4.png" alt="配图"></p><p>Pages Data SDK 让 Web 页面应用可直接创建、查询、更新和删除云端数据，无需额外搭建后端服务与数据库，支持跨设备个人数据同步与多租户隔离的团队共享，数据凭证不暴露于前端。对读者：做轻量工具或 AI 原生小应用时可用它省掉后端，但需先确认权限模型与配额限制是否匹配业务增长。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/WXXMTPHLTH0bKV3rc35g?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="node-js-的-node-sqlite-标记为稳定" tabindex="-1">Node.js 的 node:sqlite 标记为稳定 <a class="header-anchor" href="#node-js-的-node-sqlite-标记为稳定" aria-label="Permalink to &quot;Node.js 的 node:sqlite 标记为稳定&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Node Weekly</span><time datetime="2026-11-26">2026-11-26</time></p><p>Node Weekly 第 649 期报道 node:sqlite 已标记为稳定，同时提醒注意 vendored 依赖可能让 npm audit 失真：对全新 Next.js 应用跑 npm audit 可能显示零漏洞，但单独审计其打包依赖则是另一回事。对读者：把 SQLite 纳入 Node 内置能力后，本地与边缘场景可减少原生依赖；同时应补做依赖级审计，别把框架自带的审计结果当作安全结论。</p><p class="news-entry-source"><a href="https://nodeweekly.com/issues/649" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="写了-12-个-ai-skill-三个月后-8-个在吃空饷" tabindex="-1">写了 12 个 AI Skill，三个月后 8 个在吃空饷 <a class="header-anchor" href="#写了-12-个-ai-skill-三个月后-8-个在吃空饷" aria-label="Permalink to &quot;写了 12 个 AI Skill，三个月后 8 个在吃空饷&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-26">2026-11-26</time></p><p>作者三个月写了 12 个 AI Skill，按最后改动时间盘点只剩 4 个存活，死因集中在没有真值、触发靠人记、维护成本高于收益，并给出盘点脚本与 5 条裁撤标准。对读者：给团队自建 Skill 建立「最后改动时间 + 使用频次」的定期盘点机制，比不断新增更能控制维护负担。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7712307777096007720" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
